/**
 * 検査を通った語だけ active_beta へ昇格させ、通らなかった語は理由つきで CORE から外す。
 * 中間状態（needs_human_review）は残さない（FINAL CLOSEOUT）。
 * 検査結果: docs/ai-course/adventure-v2/generated/vocab-content-validation-02.json
 */
export const CORE_BATCH_02: VocabOriginalContent[] = DRAFT.map((c) => {
  const dropped = EXCLUDED_FROM_CORE[`${c.surface}|${c.reading}`];
  return dropped
    ? {
      ...c,
      state: 'excluded_from_core' as const,
      exclusionReason: dropped.reason,
      reviewNotes: [dropped.note],
    }
    : { ...c, state: 'active_beta' as const };
});
